const input = $input.first()?.json || {};

const job_id = input.job_id || ('job_recovered_' + Date.now().toString(36));
const intent = input.intent || 'search_private';

let entities = input.entities;
let attempts = 0;
while (typeof entities === 'string' && attempts < 3) {
  try { entities = JSON.parse(entities); } catch(e) { entities = {}; break; }
  attempts++;
}
entities = entities || {};

function normalizeQueryValue(v) {
  let s = String(v ?? '');
  try { s = s.normalize('NFKC'); } catch(e) {}
  s = s.replace(/["\r\n\t]/g, ' ');
  s = s.replace(/\s+/g, ' ');
  s = s.trim();
  s = Array.from(s).slice(0, 200).join('');
  s = s.trim();
  return s;
}

const hasService = (entities.service != null && String(entities.service).trim() !== '');
const hasRegion = (entities.region != null && String(entities.region).trim() !== '');

if (!hasService && !input.intent) {
  throw new Error("Критическая ошибка: Данные не дошли до узла.");
}

if (intent === 'search_private' && !hasRegion) {
  throw new Error("WF2_MISSING_REGION: search_private требует непустой entities.region; поиск без региона запрещён.");
}

const service = normalizeQueryValue(entities.service);
const region = normalizeQueryValue(entities.region);
const budget_min = entities.budget_min || 0;
const budget_max = entities.budget_max || 999999999;

const GENERAL_EXCLUDE_DOMAINS = ['instagram.com', 'threads.com', 'threads.net', 'tiktok.com', 'facebook.com'];

const GENERAL_TEMPLATES = [
  { query_id: 'G1', phrase: (s, r) => `ищу ${s} в ${r}` },
  { query_id: 'G2', phrase: (s, r) => `нужен ${s} в ${r}` },
  { query_id: 'G3', phrase: (s, r) => `нужно ${s} в ${r}` },
  { query_id: 'G4', phrase: (s, r) => `требуется ${s} в ${r}` },
  { query_id: 'G5', phrase: (s, r) => `посоветуйте специалиста по ${s} в ${r}` },
  { query_id: 'G6', phrase: (s, r) => `дайте контакты по ${s} в ${r}` },
  { query_id: 'G7', phrase: (s, r) => `поделитесь контактами по ${s} в ${r}` }
];

const DEMAND_RECOMMENDATION_TEMPLATES = [
  { query_id: 'DR1', phrase: (s, r) => `посоветуйте мастера по ${s} в ${r}` },
  { query_id: 'DR2', phrase: (s, r) => `посоветуйте бригаду по ${s} в ${r}` },
  { query_id: 'DR3', phrase: (s, r) => `посоветуйте подрядчика по ${s} в ${r}` },
  { query_id: 'DR4', phrase: (s, r) => `нужен исполнитель по ${s} в ${r}` },
  { query_id: 'DR5', phrase: (s, r) => `нужна бригада по ${s} в ${r}` },
  { query_id: 'DR6', phrase: (s, r) => `ищу мастера по ${s} в ${r}` },
  { query_id: 'DR7', phrase: (s, r) => `ищу подрядчика по ${s} в ${r}` },
  { query_id: 'DR8', phrase: (s, r) => `кого посоветуете по ${s} в ${r}` },
  { query_id: 'DR9', phrase: (s, r) => `дайте контакт мастера по ${s} в ${r}` },
  { query_id: 'DR10', phrase: (s, r) => `поделитесь контактом мастера по ${s} в ${r}` }
];

const V1_TEMPLATES = [
  { query_id: 'V1_1',  phrase: (s, r) => `ищу ${s} ${r}` },
  { query_id: 'V1_2',  phrase: (s, r) => `нужно ${s} ${r}` },
  { query_id: 'V1_3',  phrase: (s, r) => `требуется ${s} ${r}` },
  { query_id: 'V1_4',  phrase: (s, r) => `${s} ${r} кто возьмется` },
  { query_id: 'V1_5',  phrase: (s, r) => `${s} ${r} кто может выполнить` },
  { query_id: 'V1_6',  phrase: (s, r) => `${s} ${r} ищу исполнителя` },
  { query_id: 'V1_7',  phrase: (s, r) => `${s} ${r} нужен исполнитель` },
  { query_id: 'V1_8',  phrase: (s, r) => `${s} ${r} посоветуйте исполнителя` },
  { query_id: 'V1_9',  phrase: (s, r) => `${s} ${r} кого посоветуете` },
  { query_id: 'V1_10', phrase: (s, r) => `${s} ${r} дайте контакты` },
  { query_id: 'V1_11', phrase: (s, r) => `${s} ${r} поделитесь контактами` }
];

const queries = [];

if (intent === 'search_private') {
  const svcKeyword = service;

  for (const tpl of GENERAL_TEMPLATES) {
    const qString = tpl.phrase(svcKeyword, region);
    queries.push({ json: { query: qString, query_id: tpl.query_id, source_platform: 'general', retrieval_profile: 'general', include_domains: [], exclude_domains: GENERAL_EXCLUDE_DOMAINS.slice(), region, job_id, service, budget_min, budget_max, intent } });
  }

  for (const tpl of DEMAND_RECOMMENDATION_TEMPLATES) {
    const qString = tpl.phrase(svcKeyword, region);
    queries.push({ json: { query: qString, query_id: tpl.query_id, source_platform: 'general', retrieval_profile: 'general', include_domains: [], exclude_domains: GENERAL_EXCLUDE_DOMAINS.slice(), region, job_id, service, budget_min, budget_max, intent } });
  }

  queries.push({ json: { query: `посоветуйте исполнителя ${service} ${region}`, query_id: 'T1', source_platform: 'telegram', retrieval_profile: 'telegram_post', include_domains: ['t.me'], exclude_domains: [], region, job_id, service, budget_min, budget_max, intent } });

  queries.push({ json: { query: `нужен исполнитель для ${service} в ${region}`, query_id: 'FR1', source_platform: 'freelance.ru', retrieval_profile: 'freelance_task', include_domains: ['freelance.ru'], exclude_domains: [], region, job_id, service, budget_min, budget_max, intent } });

  for (const tpl of V1_TEMPLATES) {
    const qString = tpl.phrase(svcKeyword, region);
    queries.push({ json: { query: qString, query_id: tpl.query_id, v1_intent_id: tpl.query_id, source_platform: 'vk', retrieval_profile: 'vk_post', include_domains: ['vk.com'], exclude_domains: [], region, job_id, service, budget_min, budget_max, intent } });
  }

  (function() {
    try {
      const fanoutKey = 'wf2_v1_fanout_' + job_id;
      const sd = $getWorkflowStaticData('global');
      const now = Date.now();
      for (const k of Object.keys(sd)) {
        if (k.indexOf('wf2_v1_fanout_') === 0 && sd[k] && sd[k].ts && (now - sd[k].ts > 86400000)) {
          delete sd[k];
        }
      }
      const outcomes = {};
      for (const tpl of V1_TEMPLATES) { outcomes[tpl.query_id] = 'PENDING'; }
      sd[fanoutKey] = {
        ts: now,
        raw_admitted: 0,
        seen_provider_post_ids: {},
        auth_stop: false,
        outcomes: outcomes,
        counters: {
          attempted: 0,
          succeeded: 0,
          failed: 0,
          skipped: 0,
          duplicates: 0,
          raw_total: 0,
          normalized_total: 0,
          emitted_total: 0,
          classifier_input_total: 0
        }
      };
    } catch(e) { /* fail-open */ }
  })();
} else {
  queries.push({ json: { query: `${service} ${region} vsem-podryad.ru "субподряд"`, source_platform: 'vsem-podryad', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `${service} ${region} vsem-podryad.ru "заявка"`, source_platform: 'vsem-podryad', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `${service} ${region} t.me "субподряд"`, source_platform: 'telegram', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"ищем подрядчика" ${service} ${region}`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"требуется подрядчик" ${service} ${region}`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"ищем субподрядчика" ${service} ${region}`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `"требуется бригада" ${service} ${region}`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `${service} ${region} "заявка на субподряд"`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `${service} ${region} "бригада на объект"`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
  queries.push({ json: { query: `${service} ${region} "объём работ" подрядчик`, source_platform: 'general', region, job_id, service, budget_min, budget_max, intent } });
}

(function() {
  try {
    const normalize = (value) => String(value ?? '').trim().toLowerCase().replace(/\u0451/g, '\u0435').replace(/[\u2010\u2011\u2012\u2013\u2014\u2212]/g, '-');
    const diagInScope = intent === 'search_private' && normalize(service).trim() !== '' && normalize(region).trim() !== '';
    if (!diagInScope) return;
    const diagKey = 'wf2_diag_v2_' + job_id;
    const sd = $getWorkflowStaticData('global');
    const now = Date.now();
    for (const k of Object.keys(sd)) {
      if (k.startsWith('wf2_diag_v2_') && sd[k]?.ts && (now - sd[k].ts > 86400000)) {
        delete sd[k];
      }
    }
    sd[diagKey] = {
      ts: now,
      queryCount: queries.length,
      queriesByPlatform: {},
      pp1_removed_from_roster: true,
      pt1_removed_from_roster: true,
      firecrawlSearchRawTotal: 0,
      firecrawlSearchAtomicTotal: 0,
      listingRawTotal: 0,
      listingAtomicTotal: 0,
      qualityAcceptedCount: 0,
      confirmedDuplicates: 0,
      dedupUnknown: 0,
      pineconeUpsertFailures: 0
    };
    sd['wf2_accepted_' + job_id] = 0;
    for (const q of queries) {
      const p = q.json.source_platform || 'unknown';
      sd[diagKey].queriesByPlatform[p] = (sd[diagKey].queriesByPlatform[p] || 0) + 1;
    }
  } catch(e) { /* fail-open */ }
})();

return queries;

// TEMP Finalize WF2 Funnel V2 — reads transient accumulator, builds compact diagnostic
// Runs when Loop Queries completes (output 0 = DONE).
// Fail-open: any error returns original items unchanged with emit=false.

try {
  const normalize = (value) => String(value ?? '').trim().toLowerCase().replace(/\u0451/g, '\u0435').replace(/[\u2010\u2011\u2012\u2013\u2014\u2212]/g, '-');
  const items = $input.all();
  const firstItem = (items && items.length > 0) ? (items[0].json || {}) : {};

  let intent = '', service = '', region = '', jobId = '';
  try {
    const triggerData = $('Trigger').first().json;
    intent = triggerData.intent || '';
    jobId = triggerData.job_id || '';
    let entities = triggerData.entities;
    let attempts = 0;
    while (typeof entities === 'string' && attempts < 3) {
      try { entities = JSON.parse(entities); } catch(e) { entities = {}; break; }
      attempts++;
    }
    entities = entities || {};
    service = entities.service || '';
    region = entities.region || '';
  } catch(e) {}

  if (!service || !region) {
    service = firstItem.service || service;
    region = firstItem.region || region;
  }
  if (!jobId) jobId = firstItem.job_id || '';

  intent = normalize(intent);
  service = normalize(service);
  region = normalize(region);

  const inScope = intent === 'search_private' && service.trim() !== '' && region.trim() !== '';

  let emit = false;
  let diagMessage = '';
  let v1Diag = null;

  if (inScope) {
    const sd = $getWorkflowStaticData('global');
    const diagKey = 'wf2_diag_v2_' + jobId;
    const acc = sd[diagKey];
    const fanoutKey = 'wf2_v1_fanout_' + jobId;
    const fan = sd[fanoutKey];

    const lines = ['TEMP WF2 FUNNEL DIAGNOSTIC V2'];
    lines.push('Job: ' + jobId);
    lines.push('Intent: ' + intent + ' | Svc: ' + service + ' | Region: ' + region);
    if (acc) {
      lines.push('Queries: ' + (acc.queryCount || 0));
      if (acc.queriesByPlatform) {
        const plat = Object.entries(acc.queriesByPlatform).map(function(e) { return e[0] + ':' + e[1]; }).join(' ');
        lines.push('ByPlatform: ' + plat);
      }
      lines.push('SerpOrganic: ' + (acc.serperOrganicTotal || 0) + ' | URL: ' + (acc.extractedUrlTotal || 0));
      lines.push('ClassIn: ' + (acc.classificationInput || 0) + ' D:' + (acc.demandCount || 0) + ' S:' + (acc.supplyCount || 0) + ' A:' + (acc.ambiguousCount || 0));
      lines.push('Keep: ' + (acc.keepCount || 0) + ' | Reject: ' + (acc.rejectCount || 0));
      if (acc.reasonCodes) lines.push('Codes: ' + JSON.stringify(acc.reasonCodes));
      lines.push('FltPass: ' + (acc.filterEmptyPassed || 0) + ' | LoopUrl: ' + (acc.loopUrlsEntered || 0));
      lines.push('FCAtt: ' + (acc.firecrawlAttempted || 0) + ' | FCUsable: ' + (acc.firecrawlUsable || 0));
      lines.push('CntOut: ' + (acc.extractContactsOutput || 0) + ' | WithCnt: ' + (acc.contactPresenceCount || 0));
      lines.push('AppendOK: ' + (acc.appendLeadSuccessOutput || 0));
      lines.push('pp1_removed_from_roster: ' + (acc.pp1_removed_from_roster === true ? 'true' : 'false'));
      lines.push('pt1_removed_from_roster: ' + (acc.pt1_removed_from_roster === true ? 'true' : 'false'));
    }

    if (fan) {
      const c = fan.counters || {};
      lines.push('v1_templates_attempted: ' + (c.attempted || 0));
      lines.push('v1_templates_succeeded: ' + (c.succeeded || 0));
      lines.push('v1_templates_failed: ' + (c.failed || 0));
      lines.push('v1_templates_skipped: ' + (c.skipped || 0));
      const outcomes = Object.entries(fan.outcomes || {}).map(function(e){ return e[0] + '=' + e[1]; }).join(';');
      lines.push('v1_per_template_outcome: ' + outcomes);
      lines.push('v1_raw_post_count_total: ' + (c.raw_total || 0));
      lines.push('v1_normalized_post_count_total: ' + (c.normalized_total || 0));
      lines.push('v1_duplicate_count: ' + (c.duplicates || 0));
      lines.push('v1_emitted_candidate_count_total: ' + (c.emitted_total || 0));
      lines.push('v1_classifier_input_count: ' + (c.classifier_input_total || 0));

      v1Diag = {
        job_id: jobId,
        v1_templates_attempted: Number(c.attempted || 0),
        v1_provider_calls: Number(c.attempted || 0),
        v1_raw_admitted: Number((fan.raw_admitted) || 0),
        v1_cross_template_duplicates: Number(c.duplicates || 0),
        v1_emitted_to_classifier: Number(c.emitted_total || 0),
        v1_entered_url_loop: Number(0),
        v1_private_demand: Number(0),
        v1_final_accept: Number(0),
        v1_reject: Number(0),
        v1_source_outcomes: (fan.outcomes && typeof fan.outcomes === 'object') ? fan.outcomes : {},
        overall_candidate_count: Number(c.emitted_total || 0),
        overall_final_accept_count: Number(0)
      };
    }
  }

  if (inScope && sd[fanoutKey]) {
    delete sd[fanoutKey];
  }

  if (inScope) {
    diagMessage = lines.join('\n');
    if (diagMessage.length > 3500) diagMessage = diagMessage.slice(0, 3500);
    emit = true;
  }

  return items.map(function(item, idx) {
    if (idx === 0) {
      return { json: Object.assign({}, item.json, { _temp_wf2_diag_v1_emit: emit, _temp_wf2_diag_v1_message: diagMessage, v1_diagnostics: v1Diag }) };
    }
    return { json: Object.assign({}, item.json, { _temp_wf2_diag_v1_emit: false, _temp_wf2_diag_v1_message: '', v1_diagnostics: null }) };
  });
} catch(e) {
  return $input.all();
}

let jobId = '';
try { jobId = $('Trigger').first().json.job_id || ''; } catch(e) {}
if (!jobId) jobId = $input.first()?.json?.job_id || '';
if (!jobId) throw new Error('Prepare Analyst Trigger: job_id missing');

let requested_count = null;
try {
  const value = $('Trigger').first().json.requested_count;
  if (value !== undefined && value !== null && value !== '') requested_count = Number(value);
} catch(e) {}

const sd = $getWorkflowStaticData('global');
const acc = (sd && sd['wf2_diag_v2_' + jobId]) || {};
const fan = (sd && sd['wf2_v1_fanout_' + jobId]) || {};
const vk = (fan && fan.counters) || {};
const count = function(value) {
  const n = Number(value || 0);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : 0;
};

const diagnostics = {
  query_count: count(acc.queryCount),
  raw_candidates: count(acc.serperOrganicTotal) + count(acc.firecrawlSearchRawTotal) + count(acc.listingRawTotal) + count(vk.raw_total),
  atomic_url_candidates: count(acc.extractedUrlTotal) + count(acc.firecrawlSearchAtomicTotal) + count(acc.listingAtomicTotal) + count(vk.emitted_total),
  classifier_keep: count(acc.keepCount),
  pages_inspected: count(acc.firecrawlUsable),
  direct_contact_candidates: count(acc.contactPresenceCount),
  quality_accepted: count(acc.qualityAcceptedCount),
  confirmed_duplicates: count(acc.confirmedDuplicates),
  dedup_unknown: count(acc.dedupUnknown),
  pinecone_upsert_failures: count(acc.pineconeUpsertFailures),
  persisted_leads: count(acc.appendLeadSuccessOutput),
  zero_stage: 'NONE'
};

if (diagnostics.raw_candidates === 0) diagnostics.zero_stage = 'NO_RAW_CANDIDATES';
else if (diagnostics.atomic_url_candidates === 0) diagnostics.zero_stage = 'NO_ATOMIC_URLS';
else if (diagnostics.classifier_keep === 0) diagnostics.zero_stage = 'NO_CLASSIFIER_KEEP';
else if (diagnostics.pages_inspected === 0) diagnostics.zero_stage = 'NO_USABLE_PAGES';
else if (diagnostics.direct_contact_candidates === 0) diagnostics.zero_stage = 'NO_DIRECT_CONTACT';
else if (diagnostics.quality_accepted === 0) diagnostics.zero_stage = 'NO_QUALITY_ACCEPT';
else if (diagnostics.quality_accepted > 0 && diagnostics.confirmed_duplicates >= diagnostics.quality_accepted && diagnostics.persisted_leads === 0) diagnostics.zero_stage = 'ALL_CONFIRMED_DUPLICATES';
else if (diagnostics.quality_accepted > 0 && diagnostics.persisted_leads === 0) diagnostics.zero_stage = 'PERSISTENCE_FAILURE';

const accepted_count = count(sd && sd['wf2_accepted_' + jobId]);

return [{
  json: {
    job_id: jobId,
    entity_type: 'lead',
    accepted_count: accepted_count,
    requested_count: requested_count,
    search_diagnostics_json: JSON.stringify(diagnostics)
  }
}];

const item = $input.first();
if (!item || !item.json) return [{ json: { skip: true, serper_unusable: true } }];
const ctx = item.json;
const query = ctx.query;
const sp = ctx.source_platform;
const rg = ctx.region;
const sv = ctx.service;
const itn = ctx.intent;
const jid = ctx.job_id;
const qid = ctx.query_id || '';
if (!query || !sp || !rg || !sv || !itn || !jid) return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_CONTEXT_MISSING' } }];
if (!item.binary || !item.binary.serperResult) return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_RESPONSE_MISSING' } }];
let raw;
try { const buf = await this.helpers.getBinaryDataBuffer(0, 'serperResult'); raw = buf.toString('utf8').replace(/^\uFEFF/, '').trim(); }
catch(e) { return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_RESPONSE_READ_FAILED' } }]; }
if (!raw) return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_RESPONSE_EMPTY' } }];
let parsed;
try { parsed = JSON.parse(raw); } catch(e) { return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_RESPONSE_MALFORMED' } }]; }
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return [{ json: { skip: true, serper_unusable: true, error: 'WF2_SERPER_RESPONSE_INVALID' } }];
const organic = Array.isArray(parsed.organic) ? parsed.organic : (Array.isArray(parsed.serperResult && parsed.serperResult.organic) ? parsed.serperResult.organic : []);

// ── RETRIEVAL PROFILES (host gate evaluated before path gate) ──
// URL parser compatibility: use native URL when available; otherwise
// deterministic manual absolute HTTP(S) parser. Native failure stays fail-closed.
const URL_AVAILABLE = (typeof URL === 'function');
const urlParserMode = URL_AVAILABLE ? 'native' : 'manual_fallback';
function manualParseAbsoluteUrl(raw) {
  const s = String(raw == null ? '' : raw).trim();
  const m = s.match(/^(https?):\/\/([^/?#]*)(\/[^?#]*)?/i);
  if (!m) return null;
  const scheme = m[1].toLowerCase();
  if (scheme !== 'http' && scheme !== 'https') return null;
  const authority = m[2];
  if (!authority) return null;
  if (/[\s\\]/.test(authority)) return null;
  let hostPort = authority;
  const atIdx = hostPort.lastIndexOf('@');
  if (atIdx !== -1) hostPort = hostPort.slice(atIdx + 1);
  if (!hostPort) return null;
  let host = hostPort;
  const colonIdx = hostPort.lastIndexOf(':');
  if (colonIdx !== -1) {
    const port = hostPort.slice(colonIdx + 1);
    if (port === '' || !/^\d+$/.test(port)) return null;
    host = hostPort.slice(0, colonIdx);
  }
  if (!host) return null;
  if (host.indexOf(':') !== -1) return null;
  host = host.toLowerCase();
  if (host.endsWith('.')) host = host.slice(0, -1);
  if (!host) return null;
  if (host.startsWith('www.')) host = host.slice(4);
  if (!host) return null;
  const pathname = m[3] || '/';
  return { host: host, pathname: pathname };
}
function parseUrlGate(url) {
  if (URL_AVAILABLE) {
    try {
      const u = new URL(url);
      if (u.protocol !== 'http:' && u.protocol !== 'https:') return null;
      let h = u.hostname.toLowerCase();
      if (h.endsWith('.')) h = h.slice(0, -1);
      if (h.startsWith('www.')) h = h.slice(4);
      return { host: h, pathname: u.pathname };
    } catch(e) { return null; }
  }
  return manualParseAbsoluteUrl(url);
}
function isVkPost(url) {
  const p = parseUrlGate(url);
  if (!p) return false;
  if (!(p.host === 'vk.com' || p.host.endsWith('.vk.com'))) return false;
  return /^\/wall-?\d+_\d+$/.test(p.pathname);
}
function isTelegramPost(url) {
  const p = parseUrlGate(url);
  if (!p) return false;
  if (!(p.host === 't.me' || p.host === 'telegram.me')) return false;
  return /^\/s\/[^/]+\/\d+\/?$/.test(p.pathname) || /^\/[^/]+\/\d+\/?$/.test(p.pathname);
}
function isFreelanceTask(url) {
  const p = parseUrlGate(url);
  return !!(p && p.host === 'freelance.ru' && p.pathname.startsWith('/task/view/'));
}
function isPoiskProOrder(url) {
  const p = parseUrlGate(url);
  if (!p || p.host !== 'poisk-pro.ru') return false;
  return /^\/order\/[0-9]+(?:\/[^/]+)?\/?$/.test(p.pathname);
}
const PETROVICH_FORBIDDEN = new Set(['orders-btob','profile','profiles','member','members','catalog','catalogue','master','masters']);
function isPetrovichOrder(url) {
  const p = parseUrlGate(url);
  if (!p || p.host !== 'pro.petrovich.ru') return false;
  let path = p.pathname;
  if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
  const parts = path.split('/');
  if (parts[0] !== '') return false;
  const segs = parts.slice(1);
  if (segs.some(function(s){ return s === ''; })) return false;
  if (segs.length === 0) return false;
  const orderIdx = segs.indexOf('orders');
  if (orderIdx === -1) return false;
  if (segs.indexOf('orders', orderIdx + 1) !== -1) return false;
  if (orderIdx > 1) return false;
  if (orderIdx + 1 >= segs.length) return false;
  if (!/^[0-9]+$/.test(segs[segs.length - 1])) return false;
  for (let i = 0; i < orderIdx; i++) { if (PETROVICH_FORBIDDEN.has(segs[i])) return false; }
  for (let i = orderIdx + 1; i < segs.length - 1; i++) { if (PETROVICH_FORBIDDEN.has(segs[i])) return false; }
  return true;
}
function profilePass(intent, rp, url) {
  if (intent !== 'search_private') return true;
  if (rp === 'vk_post') return isVkPost(url);
  if (rp === 'telegram_post') return isTelegramPost(url);
  if (rp === 'poisk_pro_order') return isPoiskProOrder(url);
  if (rp === 'petrovich_order') return isPetrovichOrder(url);
  if (rp === 'freelance_task') return isFreelanceTask(url);
  if (rp === 'general') return parseUrlGate(url) !== null;
  return true;
}

// ── JOB-SCOPED ACQUISITION URL DEDUPE (before classification/scrape) ──
function normalizeSourceUrl(raw) {
  let s = String(raw == null ? '' : raw).trim();
  if (!s) return '';
  s = s.replace(/^https?:\/\//i, '');
  const hash = s.indexOf('#');
  if (hash !== -1) s = s.slice(0, hash);
  const q = s.indexOf('?');
  if (q !== -1) s = s.slice(0, q);
  s = s.toLowerCase();
  s = s.replace(/^www\./, '');
  s = s.replace(/\/+$/, '');
  return s;
}
function urlSeen(jidArg, normUrl) {
  try {
    if (!jidArg) return false;
    const sd = $getWorkflowStaticData('global');
    const key = 'wf2_acq_url_' + jidArg;
    const now = Date.now();
    for (const k of Object.keys(sd)) {
      if (k.indexOf('wf2_acq_url_') === 0 && sd[k] && sd[k].ts && (now - sd[k].ts > 86400000)) delete sd[k];
    }
    if (!sd[key]) { sd[key] = { ts: now, urls: {} }; return false; }
    sd[key].ts = now;
    return sd[key].urls[normUrl] === true;
  } catch(e) { return false; }
}
function markUrlSeen(jidArg, normUrl) {
  try {
    if (!jidArg) return;
    const sd = $getWorkflowStaticData('global');
    const key = 'wf2_acq_url_' + jidArg;
    if (!sd[key]) sd[key] = { ts: Date.now(), urls: {} };
    sd[key].urls[normUrl] = true;
  } catch(e) {}
}

const SOURCE_TARGETED = new Set(['youla','vk','telegram','poisk-pro','petrovich','vsem-podryad']);
const limit = SOURCE_TARGETED.has(sp) ? 10 : 3;
const rp = (ctx.retrieval_profile != null) ? ctx.retrieval_profile : null;
const topN = organic.slice(0, limit);

function clipS(s, n) { s = (s == null) ? '' : String(s); return s.length > n ? s.slice(0, n) : s; }
function traceKey(rank, url) { return [jid, query, String(rank), url].join('|'); }
function dateLikeMeta(entry) {
  const out = [];
  try {
    if (!entry || typeof entry !== 'object') return out;
    for (const k of Object.keys(entry)) {
      if (/date|time|publish|posted|created|updated/i.test(k)) {
        const v = entry[k];
        if (v == null) continue;
        if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') out.push({ field_name: k, value: clipS(v, 120) });
      }
    }
  } catch(e) {}
  return out;
}
function serperDateRaw(entry) {
  if (!entry || typeof entry !== 'object') return '';
  const v = entry.date;
  if (v === undefined || v === null) return '';
  const t = typeof v;
  if (t === 'string' || t === 'number' || t === 'boolean') {
    const s = String(v);
    return s.length > 120 ? s.slice(0, 120) : s;
  }
  return '';
}
function buildTop10Diag() {
  const rows = [];
  try {
    const max = Math.min(organic.length, 10);
    for (let i = 0; i < max; i++) {
      const e = organic[i];
      const rank = i + 1;
      let source_profile_match = false;
      let selected_by_remediated_logic = false;
      let selection_reject_reason = '';
      if (rank > limit) {
        selection_reject_reason = 'OUTSIDE_LIMIT';
      } else if (!e || !e.link) {
        selection_reject_reason = 'MISSING_LINK';
      } else if (!profilePass(itn, rp, e.link)) {
        selection_reject_reason = 'OFF_PROFILE';
      } else {
        source_profile_match = true;
        selected_by_remediated_logic = true;
      }
      rows.push({
        rank: rank,
        source_profile_match: source_profile_match,
        selected_by_remediated_logic: selected_by_remediated_logic,
        selection_reject_reason: selection_reject_reason,
        link: clipS(e && e.link, 500),
        title: clipS(e && e.title, 250),
        snippet: clipS(e && e.snippet, 500),
        raw_keys: (e && typeof e === 'object') ? Object.keys(e) : [],
        date_like_metadata: dateLikeMeta(e)
      });
    }
  } catch(e) {}
  return rows;
}

const results = [];
for (let idx = 0; idx < topN.length; idx++) {
  const entry = topN[idx];
  if (!entry || !entry.link) continue;
