// ── Classify Private Candidates v5 zone rules ──
// Deterministic DEMAND/SUPPLY/AMBIGUOUS classification for search_private.
// Non-search_private items passthrough unchanged.
// SUPPLY candidates are rejected before Firecrawl.

const classificationVersion = "private_rules_v5";
const classifierBuildId = "v5_zone_rules_001";

function getIntent(item) {
  if (item.json && item.json.intent) return item.json.intent;
  try {
    const ti = $('Trigger').first();
    if (ti && ti.json && ti.json.intent) return ti.json.intent;
  } catch(e) {}
  return '';
}
function hostname(url) {
  if (!url || typeof url !== 'string') return '';
  let s = url.trim().toLowerCase();
  const schemeIdx = s.indexOf('://');
  if (schemeIdx !== -1) s = s.slice(schemeIdx + 3);
  const slashIdx = s.indexOf('/');
  if (slashIdx !== -1) s = s.slice(0, slashIdx);
  const colonIdx = s.lastIndexOf(':');
  if (colonIdx !== -1) s = s.slice(0, colonIdx);
  if (s.startsWith('www.')) s = s.slice(4);
  return s;
}
function pathname(url) {
  if (!url || typeof url !== 'string') return '';
  let s = url.trim().toLowerCase();
  const schemeIdx = s.indexOf('://');
  if (schemeIdx !== -1) s = s.slice(schemeIdx + 3);
  const slashIdx = s.indexOf('/');
  if (slashIdx === -1) return '/';
  s = s.slice(slashIdx);
  const qIdx = s.indexOf('?');
  if (qIdx !== -1) s = s.slice(0, qIdx);
  const fIdx = s.indexOf('#');
  if (fIdx !== -1) s = s.slice(0, fIdx);
  return s;
}
function hasServicePath(url) {
  const p = pathname(url);
  return p.includes('/uslugi/') || p.includes('/promo/') || p.includes('/service/') || p.includes('/remont/') || p.includes('montazh') || p.includes('montaj') || p.includes('ventil') || p.includes('ventilyats');
}
function hasServiceContext(text) {
  return text.includes('монтаж') || text.includes('вентиляц') || text.includes('ventil') || text.includes('ventilyats');
}
function isProfiHost(url) { const h = hostname(url); return h === 'profi.ru' || h.endsWith('.profi.ru'); }
function isYoulaHost(url) { const h = hostname(url); return h === 'youla.ru' || h.endsWith('.youla.ru'); }
function isProfiServiceZone(url) { if (!isProfiHost(url)) return false; const p = pathname(url); return /^\/geo-[^/]+\/remont(?:\/|$)/.test(p); }
function isYoulaServiceZone(url, lower) { if (!isYoulaHost(url)) return false; const p = pathname(url); return p.includes('/uslugi/') && hasServiceContext(lower); }
function isPoiskProHost(url) { const h = hostname(url); return h === 'poisk-pro.ru' || h.endsWith('.poisk-pro.ru'); }
function isPetrovichHost(url) { const h = hostname(url); return h === 'pro.petrovich.ru' || h.endsWith('.pro.petrovich.ru'); }
function isPoiskProOrder(url) { if (!isPoiskProHost(url)) return false; const p = pathname(url); return /^\/order\/\d+(?:\/|$)/.test(p); }
function isPetrovichOrder(url) { if (!isPetrovichHost(url)) return false; const p = pathname(url); const hasOrdersPath = p.includes('/orders/') || p.includes('/orders-btob/'); if (!hasOrdersPath) return false; return /\/\d+$/.test(p); }

function isR00ServiceProviderPage(url, lower) {
  if (isProfiServiceZone(url)) return true;
  if (isYoulaServiceZone(url, lower)) return true;
  if (!hasServicePath(url)) return false;
  return lower.includes('под ключ') || lower.includes('компания') || lower.includes('стоимость') || lower.includes('цены') || lower.includes('скидкой') || lower.includes('специалиста готовы') || lower.includes('специалисты готовы') || lower.includes('найдите частного') || lower.includes('исполнителей') || lower.includes('платная доска объявлений') || lower.includes('хотите установить') || lower.includes('хотите купить');
}
function isR01MarketplacePromo(url, lower) {
  if (!isProfiHost(url)) return false;
  const p = pathname(url);
  if (!p.includes('/promo/')) return false;
  return lower.includes('специалиста готовы') || lower.includes('специалисты готовы') || lower.includes('найдите') || lower.includes('скидкой') || lower.includes('на нашем сайте') || lower.includes('рубл') || lower.includes('исполнителей');
}
function isR02ExecutorCatalog(lower) {
  const hasExecListing = lower.includes('исполнител');
  if (!hasExecListing) return false;
  return hasServiceContext(lower);
}
function isR03CompanyMarketing(lower) {
  if (!lower.includes('компания')) return false;
  return hasServiceContext(lower);
}
function isR04SelfPromotion(lower) {
  if (lower.includes('наша компания')) return true;
  if (lower.includes('принимает заказы') && !lower.includes('ищу')) return true;
  if (lower.includes('оказываем услуги')) return true;
  if (lower.includes('выполняем') && lower.includes('монтаж')) return true;
  if (lower.includes('бригада') && lower.includes('предлагает')) return true;
  if (lower.includes('звоните')) return true;
  if (lower.includes('оставить заявку') && (lower.includes('монтаж') || lower.includes('вентиляц'))) return true;
  return false;
}
function isR05Demand(url, lower) {
  const p = pathname(url);
  if (p.includes('/request/') || p.includes('/requests/')) return true;
  if (p.includes('/zayavk') || p.includes('/zakaz')) return true;
  if (lower.includes('ищу бригаду')) return true;
  if (lower.includes('нужна бригада')) return true;
  if (lower.includes('ищем исполнител')) return true;
  if (lower.includes('посоветуйте бригаду')) return true;
  if (lower.includes('поделитесь контактами')) return true;
  if (lower.includes('кто может сделать')) return true;
  if (lower.includes('ищем мастер')) return true;
  if (lower.includes('ищу мастер')) return true;
  if (lower.includes('заявки на субподряд')) return true;
  const hasReq = lower.includes('требуется') && (lower.includes('выполнить') || lower.includes('сделать'));
  const hasResources = lower.includes('расходники предоставим') || lower.includes('леса предоставим') || lower.includes('объемы внушительные');
  const hasRegion = lower.includes('регион:');
  const hasAddress = lower.includes('адрес:');
  const taskSignals = [hasReq, hasResources, hasRegion, hasAddress].filter(Boolean).length;
  if (taskSignals >= 2) return true;
  return false;
}

function buildDebug(url, title, snippet, idx) {
  const lower = (title + ' ' + snippet).toLowerCase();
  const path = pathname(url);
  return {
    classifier_build_id: classifierBuildId,
    input_index: idx,
    path_normalized: path,
    lower_preview: lower.slice(0, 150),
    predicates: {
      hasServicePath: hasServicePath(url),
      hasServiceContext: hasServiceContext(lower),
      isProfiHost: isProfiHost(url),
      isYoulaHost: isYoulaHost(url),
      isProfiServiceZone: isProfiServiceZone(url),
      isYoulaServiceZone: isYoulaServiceZone(url, lower),
      isPoiskProHost: isPoiskProHost(url),
      isPetrovichHost: isPetrovichHost(url),
      isPoiskProOrder: isPoiskProOrder(url),
      isPetrovichOrder: isPetrovichOrder(url),
      R00_SERVICE_PROVIDER_PAGE: isR00ServiceProviderPage(url, lower),
      R01_MARKETPLACE_PROMO: isR01MarketplacePromo(url, lower),
      R02_EXECUTOR_CATALOG: isR02ExecutorCatalog(lower),
      R03_COMPANY_MARKETING: isR03CompanyMarketing(lower),
      R04_SELF_PROMOTION: isR04SelfPromotion(lower),
      R05_DEMAND: isR05Demand(url, lower)
    }
  };
}

function classify(url, title, snippet) {
  const lower = (title + ' ' + snippet).toLowerCase();
  if (isPoiskProOrder(url))                     return { cls: 'DEMAND', codes: ['R05A_POISKPRO_ORDER'] };
  if (isPetrovichOrder(url))                     return { cls: 'DEMAND', codes: ['R05B_PETROVICH_ORDER'] };
  if (isR00ServiceProviderPage(url, lower))      return { cls: 'SUPPLY', codes: ['R00_SERVICE_PROVIDER_PAGE'] };
  if (isR01MarketplacePromo(url, lower))          return { cls: 'SUPPLY', codes: ['R01_MARKETPLACE_PROMO'] };
  if (isR02ExecutorCatalog(lower))                return { cls: 'SUPPLY', codes: ['R02_EXECUTOR_CATALOG'] };
  if (isR03CompanyMarketing(lower))               return { cls: 'SUPPLY', codes: ['R03_COMPANY_MARKETING'] };
  if (isR04SelfPromotion(lower))                  return { cls: 'SUPPLY', codes: ['R04_SELF_PROMOTION'] };
  if (isR05Demand(url, lower))                    return { cls: 'DEMAND', codes: ['R05_DEMAND'] };
  return { cls: 'AMBIGUOUS', codes: ['R06_DEFAULT'] };
}

const inputItems = $input.all();
