const inputItem = $input.first();
if (!inputItem || !inputItem.json) {
  return [{ json: { no_results: true, pre_persistence_pass: false, quality_decision: 'REJECT', error: 'WF2_CONTEXT_MISSING' } }];
}
const ctx = inputItem.json;
