}

let markdown = '';
let metadata = {};
let fc = null;
let fcRaw = null;
let fcData = null;
let scrapeUsable = false;
let content_source = '';

const searchMarkdown = (typeof ctx.search_markdown === 'string' && ctx.search_markdown.trim().length > 0) ? ctx.search_markdown.trim() : '';

if (searchMarkdown) {
  markdown = searchMarkdown;
  metadata = {};
  scrapeUsable = true;
  content_source = 'FIRECRAWL_SEARCH';
} else {
  if (!inputItem.binary?.firecrawlResult) {
    return [{ json: { no_results: true, pre_persistence_pass: false, quality_decision: 'REJECT', error: 'WF2_FIRECRAWL_RESPONSE_MISSING', source_url: source_url, job_id: job_id } }];
  }
  let fcText;
  try {
    const fcBuffer = await this.helpers.getBinaryDataBuffer(0, 'firecrawlResult');
    fcText = fcBuffer.toString('utf8').replace(/^\uFEFF/, '').trim();
  } catch (error) {
    const msg = String(error?.message || error).slice(0, 200);
    return [{ json: { no_results: true, pre_persistence_pass: false, quality_decision: 'REJECT', error: 'WF2_FIRECRAWL_RESPONSE_READ_FAILED: ' + msg, source_url: source_url, job_id: job_id } }];
