var GENERIC_STOPWORDS_SET = {};
['услуга','услуги','работа','работы','выполнение','выполнить','оказание','оказать','нужен','нужна','нужно','требуется','ищу','заказ','заказать','мастер','специалист','бригада','по','для','на','в','с','и'].forEach(function(w){GENERIC_STOPWORDS_SET[w]=true;});

