function parseServiceClause(serviceStr) {
  var s = normalizeServiceText(serviceStr);
  var orParts = s.split(/\s+или\s+/);
  var alternatives = [];
  for (var i=0;i<orParts.length;i++) {
    var subParts = orParts[i].split(/\s*\/\s*/);
    for (var j=0;j<subParts.length;j++) {
      var sub = subParts[j].trim(); if (!sub) continue;
      var andParts = sub.split(/\s+и\s+/);
      var conjuncts = [];
      for (var k=0;k<andParts.length;k++) {
        var ap = andParts[k].trim(); if (!ap) continue;
        var tokens = removeStopwords(tokenize(ap));
        tokens = stemTokens(tokens);
        conjuncts.push(tokens);
      }
      if (conjuncts.length>0) alternatives.push(conjuncts);
    }
