  return alternatives;
}

function containsContiguousSeq(haystack, needle) {
  if (needle.length===0) return false;
  for (var start=0;start<=haystack.length-needle.length;start++) {
    var match=true;
    for (var ti=0;ti<needle.length;ti++) { if (haystack[start+ti]!==needle[ti]){match=false;break;} }
    if (match) return true;
  }
  return false;
}

function unitSatisfiesAlt(unitTokens, alternative) {
  for (var c=0;c<alternative.length;c++) {
    var conj=alternative[c]; if (conj.length===0) continue;
    if (!containsContiguousSeq(unitTokens, conj)) return false;
  }
  return true;
}

function splitEvidenceUnits(text) {
  var units=[];
  var paragraphs=text.split(/\n\s*\n/);
  for (var p=0;p<paragraphs.length;p++) {
    var para=paragraphs[p].trim(); if(!para) continue;
    var headingParts=para.split(/(?:^|\n)#{1,6}\s+/);
    for (var h=0;h<headingParts.length;h++) {
      var hp=headingParts[h].trim(); if(!hp) continue;
      var listParts=hp.split(/(?:^|\n)[-*•]\s+/);
      for (var l=0;l<listParts.length;l++) { var lp=listParts[l].trim(); if(lp) units.push(lp); }
    }
  }
  return units.length>0?units:[text];
}

function unitHasNegatedMatch(rawUnit, alternative) {
  var lower=rawUnit.toLowerCase();
  if (!/\b(?:не|без|кроме|исключая)\b/.test(lower)) return false;
  var rawTokens=lower.split(/\s+/);
  var negPositions=[];
  for (var rt=0;rt<rawTokens.length;rt++) { if (/^(не|без|кроме|исключая)$/.test(rawTokens[rt])) negPositions.push(rt); }
  if (negPositions.length===0) return false;
  for (var c=0;c<alternative.length;c++) {
    var conj=alternative[c]; if (conj.length===0) continue;
    for (var rt2=0;rt2<=rawTokens.length-conj.length;rt2++) {
      var cm=true;
      for (var ct=0;ct<conj.length;ct++) { if (stemWord(normalizeServiceText(rawTokens[rt2+ct]))!==conj[ct]){cm=false;break;} }
      if (cm) {
        for (var np=0;np<negPositions.length;np++) { if (Math.abs(negPositions[np]-rt2)<=3) return true; }
      }
    }
  }
  return false;
}

function computeServiceMatch(ctxServiceArg, evidenceText) {
  if (!ctxServiceArg||ctxServiceArg.trim()==='') return true;
  var alternatives=parseServiceClause(ctxServiceArg);
  if (alternatives.length===0) return true;
  var rawUnits=splitEvidenceUnits(evidenceText);
  var evidenceUnits=rawUnits.map(function(u){return stemTokens(removeStopwords(tokenize(normalizeServiceText(u))));});
  for (var alt=0;alt<alternatives.length;alt++) {
    for (var eu=0;eu<evidenceUnits.length;eu++) {
      if (unitSatisfiesAlt(evidenceUnits[eu], alternatives[alt])) {
        if (!unitHasNegatedMatch(rawUnits[eu], alternatives[alt])) return true;
      }
    }
  }
  return false;
}

