var MOSCOW_ALIASES = ['мск','москва'];

var ADJ_SUFFIXES = ['ого','его','ому','ему','ым','им','ом','ем','ая','яя','ое','ее','ые','ие','ых','их'];
var CONSONANT_SUFFIXES = ['а','у','ом','е','ы','ов','ам','ах','ами'];
var RUS_CONSONANTS = 'бвгджзклмнпрстфхцчшщ';

function generateTokenSurfaceForms(token) {
