  else if (token.endsWith('я')) { s = token.slice(0, -1); forms.push(s + 'и', s + 'е', s + 'ю', s + 'ей', s + 'ею'); }
  else if (token.endsWith('ь')) { s = token.slice(0, -1); forms.push(s + 'и', s + 'ю', s + 'ью', s + 'е'); }
  else if (token.endsWith('й')) { s = token.slice(0, -1); forms.push(s + 'я', s + 'ю', s + 'ем', s + 'е'); }
  else if (RUS_CONSONANTS.indexOf(token.charAt(token.length - 1)) !== -1) { for (var j = 0; j < CONSONANT_SUFFIXES.length; j++) forms.push(token + CONSONANT_SUFFIXES[j]); }
