}

function generateFullPhraseForms(region) {
  var tokens = region.split(/\s+/).filter(function (t) { return t.length > 0; });
  if (tokens.length === 0) return [region];
  var tokenForms = tokens.map(generateTokenSurfaceForms);
  var results = [''];
  for (var i = 0; i < tokenForms.length; i++) {
    var next = [];
    for (var a = 0; a < results.length; a++) {
      for (var b = 0; b < tokenForms[i].length; b++) {
        next.push(results[a] ? (results[a] + ' ' + tokenForms[i][b]) : tokenForms[i][b]);
      }
    }
    results = next;
  }
  return results;
}

function buildRequestedForms(normRegion) {
  var forms = [];
  if (SPB_ALIASES.indexOf(normRegion) !== -1) {
    forms = SPB_ALIASES.slice();
    generateFullPhraseForms('петербург').forEach(function (f) { forms.push(f); });
    generateFullPhraseForms('санкт петербург').forEach(function (f) { forms.push(f); });
  } else if (MOSCOW_ALIASES.indexOf(normRegion) !== -1) {
    forms = MOSCOW_ALIASES.slice();
    generateFullPhraseForms('москва').forEach(function (f) { forms.push(f); });
  } else {
    forms = generateFullPhraseForms(normRegion);
  }
