function transliterateCity(name) {
  // Cyrillic → latin city-name transliteration for Poisk-Pro slug fallback.
  // Only used as a deterministic slug builder for known Cyrillic city names;
  // returns '' when safe transliteration cannot be produced.
  const map = {
    'а': 'a', 'б': 'b', 'в': 'v', 'г': 'g', 'д': 'd', 'е': 'e', 'ж': 'zh',
    'з': 'z', 'и': 'i', 'й': 'y', 'к': 'k', 'л': 'l', 'м': 'm', 'н': 'n',
    'о': 'o', 'п': 'p', 'р': 'r', 'с': 's', 'т': 't', 'у': 'u', 'ф': 'f',
    'х': 'h', 'ц': 'ts', 'ч': 'ch', 'ш': 'sh', 'щ': 'sch', 'ъ': '', 'ы': 'y',
    'ь': '', 'э': 'e', 'ю': 'yu', 'я': 'ya', 'ё': 'e'
  };
  const tokens = String(name || '').toLowerCase().split(/[\s-]+/).filter(Boolean);
  if (tokens.length === 0) return '';
  const parts = [];
  for (const tok of tokens) {
    let out = '';
    for (let i = 0; i < tok.length; i++) {
      const ch = tok[i];
      if (!map.hasOwnProperty(ch)) return '';
      out += map[ch];
    }
    if (!out) return '';
    parts.push(out);
  }
  return parts.join('-');
}

function poiskProCitySlug(regionValue) {
  const r = normalize(regionValue).replace(/[.]+/g, ' ').replace(/[^а-яa-z0-9\s-]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!r) return '';
  if (CITY_ALIASES.hasOwnProperty(r)) return CITY_ALIASES[r];
