      collected: [],
      retrieved_at: new Date().toISOString()
    };

if (!Number.isInteger(state.page) || state.page < 1 || state.page > 3) {
  throw new Error('VK_PAGE_GUARD');
}
if (!Number.isInteger(state.retry_index) || state.retry_index < 0 || state.retry_index > 3) {
  throw new Error('VK_RETRY_GUARD');
}
if (state.page === 1) state.request_cursor = null;
if (state.page > 1 && (!state.request_cursor || !state.request_cursor.trim())) {
  throw new Error('VK_CURSOR_GUARD');
}

return [{ json: { _vk_context: context, _vk_state: state } }];

const inputs = $input.all();
if (inputs.length !== 1 || !inputs[0] || !inputs[0].json) throw new Error('VK_FINALIZE_CARDINALITY');
const state = inputs[0].json._vk_state;
if (!state || !Array.isArray(state.collected) || state.collected.length < 1 || state.collected.length > 300) {
  throw new Error('VK_FINALIZE_CANDIDATE_GUARD');
}
return state.collected.map((candidate) => ({ json: candidate }));

const inputs = $input.all();
const data = inputs.length === 1 && inputs[0] && inputs[0].json ? inputs[0].json : {};
const context = data._vk_context && typeof data._vk_context === 'object' ? data._vk_context : {};
const state = data._vk_state && typeof data._vk_state === 'object' ? data._vk_state : {};
const terminalStatus = String(data._vk_terminal_status || data._vk_status || 'SOURCE_SCHEMA_ERROR');
return [{ json: {
  skip: true,
  vk_status: terminalStatus,
  provider: 'vk_api',
  source_platform: 'vk',
  retrieval_profile: 'vk_api_post',
  query: String(context.query || ''),
  query_id: String(context.query_id || ''),
  v1_intent_id: String(context.v1_intent_id || context.query_id || ''),
  service: String(context.service || ''),
  region: String(context.region || ''),
  job_id: String(context.job_id || ''),
  provider_page: Number.isInteger(state.page) ? state.page : null,
  retrieved_at: String(state.retrieved_at || new Date().toISOString())
} }];

const items = $input.all();
let jobId = '';
try { jobId = $('Extract Contacts').item.json.job_id || ''; } catch(e) {}
if (!jobId) {
  try { jobId = $('Trigger').first().json.job_id || ''; } catch(e) {}
}
if (!jobId && items.length > 0) jobId = items[0].json?.job_id || '';

let confirmedDuplicates = 0;
let dedupUnknown = 0;
const output = items.map(function(item) {
  const j = (item && item.json) ? item.json : {};
  const providerError = !!j.error || j.success === false || j.ok === false || j.status === 'error' || j.status === 'failed';
  let dedupState;
  if (providerError || !Array.isArray(j.matches)) {
    dedupState = 'DEDUP_UNKNOWN';
    dedupUnknown++;
  } else if (j.matches.length > 0) {
    dedupState = 'REAL_DUPLICATE';
    confirmedDuplicates++;
  } else {
    dedupState = 'NOT_DUPLICATE';
  }
  const out = { json: Object.assign({}, j, { dedup_state: dedupState, dedup_unique_claim: dedupState === 'NOT_DUPLICATE' }) };
  if (item && item.binary) out.binary = item.binary;
  if (item && item.pairedItem !== undefined) out.pairedItem = item.pairedItem;
  return out;
});

(function() {
  try {
    if (!jobId) return;
    const sd = $getWorkflowStaticData('global');
    const diagKey = 'wf2_diag_v2_' + jobId;
    if (sd[diagKey]) {
      sd[diagKey].confirmedDuplicates = (sd[diagKey].confirmedDuplicates || 0) + confirmedDuplicates;
      sd[diagKey].dedupUnknown = (sd[diagKey].dedupUnknown || 0) + dedupUnknown;
      sd[diagKey].ts = Date.now();
    }
  } catch(e) { /* fail-open */ }
})();

return output;
